insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000099601','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000286','reveal_answer','easy','published','Estude a série ou função indicada: $\sum_{n=1}^{\infty}\frac{1}{n^8}$. Desenvolva a resolução e justifique a conclusão.') on conflict (id) do update set subject_id=excluded.subject_id,source_id=excluded.source_id,kind=excluded.kind,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
