insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000996071','40000000-0000-4000-8000-000000099607','Leia o objetivo','Separe o que o enunciado fornece da grandeza ou conclusão que ele pede.',1),('70000000-0000-4000-8000-000000996072','40000000-0000-4000-8000-000000099607','Reconheça a ideia','O módulo dos termos é $1/n^2$; compare a série sem sinais alternados antes de classificar.',2),('70000000-0000-4000-8000-000000996073','40000000-0000-4000-8000-000000099607','Escreva a relação','Registre a definição, fórmula ou teste que se aplica antes de simplificar.',3),('70000000-0000-4000-8000-000000996074','40000000-0000-4000-8000-000000099607','Desenvolva a análise','Execute a transformação necessária e obtenha: Converge absolutamente.',4),('70000000-0000-4000-8000-000000996075','40000000-0000-4000-8000-000000099607','Confira a conclusão','Verifique sinais, domínio e hipóteses; só então compare o resultado com as quatro alternativas.',5) on conflict (id) do update set question_id=excluded.question_id,title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
