insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000996191','40000000-0000-4000-8000-000000099619','Nomeie primeiro a ideia central: Use as derivadas de $e^x$: todas valem $e^x$ e assumem valor $1$ no centro $0$.',1),('60000000-0000-4000-8000-000000996192','40000000-0000-4000-8000-000000099619','Escreva a definição ou a relação escolhida antes de substituir os dados.',2),('60000000-0000-4000-8000-000000996193','40000000-0000-4000-8000-000000099619','Ao final, teste se o resultado preserva as condições do enunciado e descarte erros de sinal, domínio ou hipótese.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000099619','O polinômio de Maclaurin até grau $4$ é $\sum_{k=0}^{4}\frac{x^k}{k!}$.','A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. Use as derivadas de $e^x$: todas valem $e^x$ e assumem valor $1$ no centro $0$. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
