insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000099620','O polinômio de Maclaurin até grau $2$ é $\sum_{k=0}^{2}\frac{x^k}{k!}$.','A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. Use as derivadas de $e^x$: todas valem $e^x$ e assumem valor $1$ no centro $0$. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
